# Unreal Engine 5.8 Python integration script for Imperium.
# Batch-imports .glb assets generated by Tripo 3D + Blender into /Game/Imperium/Models
# and optionally stages an 8x8 Roman tactical encounter or Senate chamber in the active UE 5.8 level.
#
# Run headlessly with Unreal Engine 5.8:
#   "C:\Program Files\Epic Games\UE_5.8\Engine\Binaries\Win64\UnrealEditor-Cmd.exe" ^
#     "Path\To\YourProject.uproject" ^
#     -run=pythonscript -script="C:\Users\obeid\.gemini\antigravity\scratch\Imperium\scripts\pipeline\unreal-import.py"

import glob
import json
import os
import sys

try:
    import unreal  # Available when executed inside UnrealEditor / UnrealEditor-Cmd
except ImportError:
    unreal = None


IMPERIUM_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
MODELS_DIR = os.path.join(IMPERIUM_ROOT, "assets", "models")
UE_DESTINATION_PATH = "/Game/Imperium/Models"


def find_glb_assets(models_dir=MODELS_DIR):
    return sorted(glob.glob(os.path.join(models_dir, "*.glb")))


def import_glb_assets_to_unreal(glb_files=None, destination_path=UE_DESTINATION_PATH):
    if glb_files is None:
        glb_files = find_glb_assets()

    if unreal is None:
        return {
            "imported": False,
            "reason": "Run inside UnrealEditor-Cmd.exe (-run=pythonscript) to execute unreal.* asset import.",
            "queuedFiles": [os.path.basename(p) for p in glb_files],
            "destinationPath": destination_path,
        }

    asset_tools = unreal.AssetToolsHelpers.get_asset_tools()
    import_data = unreal.AutomatedAssetImportData()
    import_data.destination_path = destination_path
    import_data.filenames = glb_files
    import_data.replace_existing = True
    imported_assets = asset_tools.import_assets_automated(import_data)
    unreal.EditorAssetLibrary.save_directory(destination_path, only_if_is_dirty=True, recursive=True)
    return {
        "imported": True,
        "count": len(imported_assets) if imported_assets else 0,
        "destinationPath": destination_path,
    }


def stage_imperium_grid_in_unreal(tile_size_cm=250.0, width=8, height=8):
    if unreal is None:
        return {"staged": False, "reason": "Unreal Python runtime not active."}

    editor_Actor_sub = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
    cube_mesh = unreal.EditorAssetLibrary.load_asset("/Engine/BasicShapes/Cube")
    spawned = 0
    for y in range(height):
        for x in range(width):
            loc = unreal.Vector((x - 3.5) * tile_size_cm, (y - 3.5) * tile_size_cm, -10.0)
            actor = editor_Actor_sub.spawn_actor_from_object(cube_mesh, loc)
            if actor:
                actor.set_actor_label(f"ImperiumTile_{x + 1}{chr(65 + y)}")
                actor.set_actor_scale3d(unreal.Vector(tile_size_cm / 100.0 * 0.96, tile_size_cm / 100.0 * 0.96, 0.2))
                spawned += 1
    return {"staged": True, "tilesSpawned": spawned}


if __name__ == "__main__":
    result = import_glb_assets_to_unreal()
    print("UNREAL_PIPELINE_REPORT:" + json.dumps(result))
